window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-73a6579d85542df9"]={"versions": [{"id": "FIG-73a6579d85542df9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des E2E-Profils 4m innerhalb der AUTOSAR-E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert den elementaren Teilschritt „Read Message Result“ der Prüffunktion <code>E2E_P04mCheck()</code> sowohl für die Client- als auch für die Serverseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext: Funktion bzw. Aktivität <code>E2E_P04mCheck()</code>.</li>\n<li>Eingangsdaten: Byte-Array <code>Data[]</code> (serialisierter Datenstrom / E2E-Header) mit Adressierung über einen Basis-Offset <code>Offset + 12</code>.</li>\n<li>Lokale Variable: <code>ReceivedMessageResult</code> vom Datentyp <code>uint8</code>.</li>\n<li>Steuerungselemente: Initialer Startknoten (Initial Node), eine Ausführungsaktion (Action Node) und ein Endknoten (Activity Final Node).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten geht der Kontrollfluss direkt in die Leseaktion über.</li>\n<li>In der Aktion wird das 2-Bit-Feld <code>MessageResult</code> aus den Bits 2 und 3 des Bytes <code>Data[Offset+12]</code> in Big-Endian-Reihenfolge extrahiert.</li>\n<li>Die Bitmanipulation erfolgt über die Vorschrift <code>ReceivedMessageResult = (Data[Offset+12] &amp; 0x30) &gt;&gt; 4</code>.</li>\n<li>Nach Zuweisung an die lokale Variable <code>ReceivedMessageResult</code> geht der Kontrollfluss zum Aktivitätsendknoten über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Extraktionsformel ist normativ verbindlich für die Implementierung der Empfängerprüfung in Profil 4m (<code>[PRS_E2E_00779]</code>).</li>\n<li>Die Maskierung mit <code>0x30</code> (Binär <code>0011 0000</code>) und anschließender Rechtsshift um 4 Stellen setzt voraus, dass Bit 0 als höchstwertiges Bit (MSB, <code>0x80</code>) gezählt wird: Bit 0 = <code>0x80</code>, Bit 1 = <code>0x40</code>, Bit 2 = <code>0x20</code>, Bit 3 = <code>0x10</code>.</li>\n<li>Entwickler müssen sicherstellen, dass <code>Data</code> mindestens die Länge <code>Offset + 13</code> Bytes aufweist, um Out-of-Bounds-Speicherzugriffe vor Ausführung dieser Operation auszuschließen.</li>\n</ul>"}, {"id": "FIG-3af36533beead4e6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des E2E-Profils 4m innerhalb der AUTOSAR-E2E-Bibliothek (AUTOSAR_PRS_E2EProtocol). Das Diagramm modelliert den elementaren Teilschritt „Read Message Result“ der Prüffunktion <code>E2E_P04mCheck()</code> sowohl für die Client- als auch für die Serverseite.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Kontext: Funktion bzw. Aktivität <code>E2E_P04mCheck()</code>.</li>\n<li>Eingangsdaten: Byte-Array <code>Data[]</code> (serialisierter Datenstrom / E2E-Header) mit Adressierung über einen Basis-Offset <code>Offset + 12</code>.</li>\n<li>Lokale Variable: <code>ReceivedMessageResult</code> vom Datentyp <code>uint8</code>.</li>\n<li>Steuerungselemente: Initialer Startknoten (Initial Node), eine Ausführungsaktion (Action Node) und ein Endknoten (Activity Final Node).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend vom Startknoten geht der Kontrollfluss direkt in die Leseaktion über.</li>\n<li>In der Aktion wird das 2-Bit-Feld <code>MessageResult</code> aus den Bits 2 und 3 des Bytes <code>Data[Offset+12]</code> in Big-Endian-Reihenfolge extrahiert.</li>\n<li>Die Bitmanipulation erfolgt über die Vorschrift <code>ReceivedMessageResult = (Data[Offset+12] &amp; 0x30) &gt;&gt; 4</code>.</li>\n<li>Nach Zuweisung an die lokale Variable <code>ReceivedMessageResult</code> geht der Kontrollfluss zum Aktivitätsendknoten über.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Extraktionsformel ist normativ verbindlich für die Implementierung der Empfängerprüfung in Profil 4m (<code>[PRS_E2E_00779]</code>).</li>\n<li>Die Maskierung mit <code>0x30</code> (Binär <code>0011 0000</code>) und anschließender Rechtsshift um 4 Stellen setzt voraus, dass Bit 0 als höchstwertiges Bit (MSB, <code>0x80</code>) gezählt wird: Bit 0 = <code>0x80</code>, Bit 1 = <code>0x40</code>, Bit 2 = <code>0x20</code>, Bit 3 = <code>0x10</code>.</li>\n<li>Entwickler müssen sicherstellen, dass <code>Data</code> mindestens die Länge <code>Offset + 13</code> Bytes aufweist, um Out-of-Bounds-Speicherzugriffe vor Ausführung dieser Operation auszuschließen.</li>\n</ul>"}], "trans": [{"from": "FIG-73a6579d85542df9", "to": "FIG-3af36533beead4e6", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
